import { execSync } from "child_process";

function getRepoName(): string {
  const remoteUrl = execSync("git config --get remote.origin.url")
    .toString()
    .trim();

  // Handles both SSH and HTTPS
  // Examples:
  // git@github.com:user/repo.git
  // https://github.com/user/repo.git

  let repo = remoteUrl
    .replace(/\.git$/, "")               // remove .git
    .split(/[:/]/)                       // split on : or /
    .pop();                             // get last segment

  return repo || "repo";
}

function slugify(input: string): string {
  return input
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")         // replace invalid chars with -
    .replace(/^-+|-+$/g, "")             // trim leading/trailing -
    .replace(/-{2,}/g, "-");             // collapse multiple -
}

function buildSourceId(): string {
  const repo = getRepoName();
  const slug = slugify(repo);

  const prefix = "gstack-code-";
  const maxLen = 32;

  const remaining = maxLen - prefix.length;

  const trimmedSlug = slug.slice(0, remaining);

  return `${prefix}${trimmedSlug}`;
}

